-- Fiscal classification is a reviewed, dated association to an exact published service version.
-- No category or rate is inferred from a label, a browser payload or a catalogue default.
create table public.service_tax_mapping_proposals(
 id uuid primary key default extensions.gen_random_uuid(),environment text not null check(environment in('DEVELOPMENT','STAGING','PRODUCTION')),service_version_id uuid not null references public.catalog_service_versions(id),service_id uuid not null references public.catalog_services(id),library_id uuid not null references public.catalog_libraries(id),service_content_hash text not null check(service_content_hash~'^[0-9a-f]{64}$'),service_snapshot jsonb not null,version integer not null check(version>0),country_code text not null references public.tax_jurisdictions(code),currency char(3)not null check(currency~'^[A-Z]{3}$'),category_code text not null references public.tax_categories(code),valid_from date not null,valid_until date,development_only boolean not null,supersedes_mapping_ids uuid[]not null default'{}'check(cardinality(supersedes_mapping_ids)<=100),expected_scope_hash text not null check(expected_scope_hash~'^[0-9a-f]{64}$'),reason text not null check(length(btrim(reason))between 10 and 1000),content_hash text not null check(content_hash~'^[0-9a-f]{64}$'),created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),idempotency_key uuid not null,unique(created_by,idempotency_key),unique(environment,service_version_id,country_code,currency,version),check(valid_until is null or valid_until>=valid_from)
);
create table public.service_tax_mapping_decisions(
 proposal_id uuid primary key references public.service_tax_mapping_proposals(id),decision text not null check(decision in('APPROVED','REJECTED')),approval_reference text not null check(length(btrim(approval_reference))between 3 and 200),reason text not null check(length(btrim(reason))between 10 and 1000),decided_by uuid not null references auth.users(id),decided_at timestamptz not null default clock_timestamp(),response_body jsonb not null
);
create table public.service_tax_category_mappings(
 id uuid primary key references public.service_tax_mapping_decisions(proposal_id),environment text not null check(environment in('DEVELOPMENT','STAGING','PRODUCTION')),service_version_id uuid not null references public.catalog_service_versions(id),service_id uuid not null references public.catalog_services(id),service_content_hash text not null,service_snapshot jsonb not null,version integer not null,country_code text not null references public.tax_jurisdictions(code),currency char(3)not null,category_code text not null references public.tax_categories(code),valid_from date not null,valid_until date,development_only boolean not null,approval_reference text not null,approved_by uuid not null references auth.users(id),approved_at timestamptz not null,content_hash text not null check(content_hash~'^[0-9a-f]{64}$'),unique(environment,service_version_id,country_code,currency,version),check(valid_until is null or valid_until>=valid_from)
);
create index service_tax_mapping_lookup_idx on public.service_tax_category_mappings(environment,service_version_id,country_code,currency,valid_from);
create table public.service_tax_mapping_supersessions(mapping_id uuid not null references public.service_tax_category_mappings(id),by_mapping_id uuid not null references public.service_tax_category_mappings(id),effective_from date not null,created_at timestamptz not null default clock_timestamp(),primary key(mapping_id,by_mapping_id),check(mapping_id<>by_mapping_id));
create function private.service_tax_mapping_reviewer_v1()returns boolean language sql stable security definer set search_path=pg_catalog,private as $$select auth.uid()is not null and auth.jwt()->>'aal'='aal2'and private.has_platform_role(array['FINANCE_MANAGER','SUPER_ADMIN'],auth.uid())$$;
revoke all on function private.service_tax_mapping_reviewer_v1()from public,anon,authenticated,service_role;
do $$declare name text;begin foreach name in array array['service_tax_mapping_proposals','service_tax_mapping_decisions','service_tax_category_mappings','service_tax_mapping_supersessions']loop
 execute format('alter table public.%I enable row level security',name);execute format('revoke all on public.%I from public,anon,authenticated,service_role',name);execute format('create trigger %I before update or delete on public.%I for each row execute function private.prevent_update_delete()',left(name,44)||'_immutable',name);
 end loop;end$$;
create function private.service_tax_mapping_environment_v1()returns text language plpgsql stable security definer set search_path=pg_catalog,private as $$declare result text;begin
 select environment into result from private.admin_execution_environment_v1 where singleton;if result is null then raise exception'SERVICE_TAX_DEPLOYMENT_ENVIRONMENT_REQUIRED'using errcode='55000';end if;return result;
end$$;
create function private.service_tax_mapping_source_v1(p_service_version_id uuid)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private as $$declare v public.catalog_service_versions%rowtype;s public.catalog_services%rowtype;begin
 select*into v from public.catalog_service_versions where id=p_service_version_id;select*into s from public.catalog_services where id=v.service_id;
 if v.id is null or v.status not in('PUBLISHED','RETIRED')or v.published_at is null or s.status='ARCHIVED'then raise exception'SERVICE_TAX_PUBLISHED_VERSION_REQUIRED'using errcode='55000';end if;
 return jsonb_build_object('service_version_id',v.id,'service_id',s.id,'library_id',s.library_id,'version',v.version,'code',s.code,'name_fr',v.name_fr,'name_ar',v.name_ar,'content_hash',v.content_hash,'published_at',v.published_at,'retired_at',v.retired_at);
end$$;
create function private.service_tax_mapping_scope_hash_v1(p_environment text,p_service_version_id uuid,p_country_code text,p_currency char(3))returns text language sql stable security definer set search_path=pg_catalog,public,private as $$
 select private.canonical_request_hash(jsonb_build_object('environment',p_environment,'service_version_id',p_service_version_id,'country_code',p_country_code,'currency',p_currency,'mappings',coalesce((select jsonb_agg(jsonb_build_object('id',m.id,'content_hash',m.content_hash,'supersessions',coalesce((select jsonb_agg(jsonb_build_object('by',s.by_mapping_id,'effective_from',s.effective_from)order by s.effective_from,s.by_mapping_id)from public.service_tax_mapping_supersessions s where s.mapping_id=m.id),'[]'::jsonb))order by m.version)from public.service_tax_category_mappings m where m.environment=p_environment and m.service_version_id=p_service_version_id and m.country_code=p_country_code and m.currency=p_currency),'[]'::jsonb)))
$$;
create function private.service_tax_mapping_period_v1(p_mapping_id uuid)returns daterange language sql stable security definer set search_path=pg_catalog,public as $$
 select daterange(m.valid_from,least(m.valid_until+1,(select min(s.effective_from)from public.service_tax_mapping_supersessions s where s.mapping_id=m.id)),'[)')from public.service_tax_category_mappings m where m.id=p_mapping_id
$$;
create function private.resolve_service_tax_category_v1(p_service_version_id uuid,p_country_code text,p_currency char(3),p_effective_on date)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private as $$
declare source jsonb;env text;ids uuid[];m public.service_tax_category_mappings%rowtype;rule jsonb;begin
 if p_effective_on is null or not isfinite(p_effective_on)or p_country_code is null or p_country_code!~'^[A-Z]{2}$'or p_currency is null or p_currency!~'^[A-Z]{3}$'then raise exception'INVALID_SERVICE_TAX_SCOPE'using errcode='22023';end if;
 env:=private.service_tax_mapping_environment_v1();source:=private.service_tax_mapping_source_v1(p_service_version_id);
 if p_country_code<>'MA'or not exists(select 1 from public.tax_jurisdictions where code=p_country_code and status='ACTIVE')then raise exception'SERVICE_TAX_JURISDICTION_UNSUPPORTED'using errcode='55000';end if;
 if p_effective_on<((source->>'published_at')::timestamptz at time zone'Africa/Casablanca')::date or(source->>'retired_at'is not null and p_effective_on>((source->>'retired_at')::timestamptz at time zone'Africa/Casablanca')::date)then raise exception'SERVICE_TAX_SOURCE_DATE_MISMATCH'using errcode='55000';end if;
 select array_agg(id order by version)into ids from public.service_tax_category_mappings mapping where mapping.environment=env and mapping.service_version_id=p_service_version_id and mapping.country_code=p_country_code and mapping.currency=p_currency and private.service_tax_mapping_period_v1(mapping.id)@>p_effective_on and exists(select 1 from public.service_tax_mapping_decisions d where d.proposal_id=mapping.id and d.decision='APPROVED');
 if coalesce(cardinality(ids),0)=0 then raise exception'SERVICE_TAX_CATEGORY_POLICY_REQUIRED'using errcode='55000';end if;
 if cardinality(ids)<>1 then raise exception'SERVICE_TAX_CATEGORY_POLICY_AMBIGUOUS'using errcode='55000';end if;
 select*into m from public.service_tax_category_mappings where id=ids[1];
 if m.service_content_hash is distinct from source->>'content_hash'then raise exception'SERVICE_TAX_SOURCE_CHANGED'using errcode='40001';end if;
 if m.development_only and env not in('DEVELOPMENT','STAGING')then raise exception'SERVICE_TAX_DEMONSTRATION_FORBIDDEN'using errcode='42501';end if;
 if not exists(select 1 from public.tax_categories where code=m.category_code and category_kind='SERVICE'and status='ACTIVE')then raise exception'SERVICE_TAX_CATEGORY_NOT_ACTIVE'using errcode='55000';end if;
 -- Validate dated availability through the existing engine, without creating or recording a monetary event.
 begin rule:=private.resolve_morocco_tax(m.category_code,p_effective_on,1);exception when sqlstate'P0002'then raise exception'SERVICE_TAX_RULE_REQUIRED'using errcode='55000';end;
 if rule->>'professional_validation_status'is distinct from'VALIDATED'then raise exception'SERVICE_TAX_RULE_VALIDATION_REQUIRED'using errcode='55000';end if;
 return jsonb_build_object('mapping_id',m.id,'version',m.version,'category_code',m.category_code,'content_hash',m.content_hash,'service_version_id',m.service_version_id,'service_content_hash',m.service_content_hash,'country_code',m.country_code,'currency',m.currency,'effective_on',p_effective_on::text,'valid_from',m.valid_from::text,'valid_until',m.valid_until::text,'approval_reference',m.approval_reference,'approved_at',m.approved_at,'environment',m.environment,'development_only',m.development_only,'service_snapshot',m.service_snapshot);
end$$;
create function public.propose_service_tax_category_mapping_v1(p_service_version_id uuid,p_expected_service_hash text,p_expected_scope_hash text,p_country_code text,p_currency char(3),p_category_code text,p_valid_from date,p_valid_until date,p_development_only boolean,p_supersedes_mapping_ids uuid[],p_reason text,p_idempotency_key uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$
declare env text;source jsonb;h text;prior public.service_tax_mapping_proposals%rowtype;proposal uuid:=extensions.gen_random_uuid();version integer;supersedes uuid[];begin
 if not coalesce(private.service_tax_mapping_reviewer_v1(),false)then raise exception'SERVICE_TAX_FINANCE_AAL2_REQUIRED'using errcode='42501';end if;
 env:=private.service_tax_mapping_environment_v1();source:=private.service_tax_mapping_source_v1(p_service_version_id);
 if source->>'content_hash'is distinct from p_expected_service_hash then raise exception'SERVICE_TAX_SOURCE_CHANGED'using errcode='40001';end if;
 if p_idempotency_key is null or p_expected_scope_hash is null or p_expected_scope_hash!~'^[0-9a-f]{64}$'or p_valid_from is null or not isfinite(p_valid_from)or(p_valid_until is not null and(not isfinite(p_valid_until)or p_valid_until<p_valid_from))or p_development_only is null or p_currency is null or p_currency!~'^[A-Z]{3}$'or length(btrim(coalesce(p_reason,'')))not between 10 and 1000 then raise exception'INVALID_SERVICE_TAX_PROPOSAL'using errcode='22023';end if;
 if p_country_code is distinct from'MA'or not exists(select 1 from public.tax_jurisdictions where code=p_country_code and status='ACTIVE')then raise exception'SERVICE_TAX_JURISDICTION_UNSUPPORTED'using errcode='55000';end if;
 if not exists(select 1 from public.tax_categories where code=p_category_code and category_kind='SERVICE'and status='ACTIVE')then raise exception'SERVICE_TAX_CATEGORY_NOT_ACTIVE'using errcode='55000';end if;
 if p_development_only and env not in('DEVELOPMENT','STAGING')then raise exception'SERVICE_TAX_DEMONSTRATION_FORBIDDEN'using errcode='42501';end if;
 if cardinality(coalesce(p_supersedes_mapping_ids,'{}'))>100 or exists(select 1 from unnest(coalesce(p_supersedes_mapping_ids,'{}'))id where id is null)then raise exception'INVALID_SERVICE_TAX_SUPERSESSION'using errcode='22023';end if;
 select coalesce(array_agg(id order by id),'{}')into supersedes from(select distinct unnest(coalesce(p_supersedes_mapping_ids,'{}'))id)ids;
 h:=private.canonical_request_hash(jsonb_build_object('environment',env,'source',source,'country',p_country_code,'currency',p_currency,'category',p_category_code,'from',p_valid_from,'until',p_valid_until,'development_only',p_development_only,'supersedes',supersedes,'scope_hash',p_expected_scope_hash,'reason',btrim(p_reason),'actor',auth.uid()));
 perform pg_advisory_xact_lock(hashtextextended('service-tax-key:'||auth.uid()::text||':'||p_idempotency_key::text,0));select*into prior from public.service_tax_mapping_proposals where created_by=auth.uid()and idempotency_key=p_idempotency_key;
 if found then if prior.content_hash is distinct from h then raise exception'IDEMPOTENCY_PAYLOAD_MISMATCH'using errcode='22000';end if;return jsonb_build_object('outcome','SERVICE_TAX_MAPPING_PROPOSED','proposal_id',prior.id,'content_hash',prior.content_hash);end if;
 perform pg_advisory_xact_lock(hashtextextended('service-tax-scope:'||env||':'||p_service_version_id::text||':'||p_country_code||':'||p_currency::text,0));
 if private.service_tax_mapping_scope_hash_v1(env,p_service_version_id,p_country_code,p_currency)is distinct from p_expected_scope_hash then raise exception'SERVICE_TAX_SCOPE_CHANGED'using errcode='40001';end if;
 if exists(select 1 from unnest(supersedes)id where not exists(select 1 from public.service_tax_category_mappings m where m.id=id and m.environment=env and m.service_version_id=p_service_version_id and m.country_code=p_country_code and m.currency=p_currency))then raise exception'SERVICE_TAX_SUPERSESSION_SCOPE_DENIED'using errcode='42501';end if;
 select coalesce(max(p.version),0)+1 into version from public.service_tax_mapping_proposals p where p.environment=env and p.service_version_id=p_service_version_id and p.country_code=p_country_code and p.currency=p_currency;
 insert into public.service_tax_mapping_proposals(id,environment,service_version_id,service_id,library_id,service_content_hash,service_snapshot,version,country_code,currency,category_code,valid_from,valid_until,development_only,supersedes_mapping_ids,expected_scope_hash,reason,content_hash,created_by,idempotency_key)values(proposal,env,p_service_version_id,(source->>'service_id')::uuid,(source->>'library_id')::uuid,p_expected_service_hash,source,version,p_country_code,p_currency,p_category_code,p_valid_from,p_valid_until,p_development_only,supersedes,p_expected_scope_hash,btrim(p_reason),h,auth.uid(),p_idempotency_key);
 insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)select library.steward_organization_id,auth.uid(),'USER','tax.service_mapping.proposed','service_tax_mapping',proposal::text,proposal,jsonb_build_object('service_version_id',p_service_version_id,'content_hash',h,'environment',env,'development_only',p_development_only),repeat('0',64)from public.catalog_libraries library where id=(source->>'library_id')::uuid;
 return jsonb_build_object('outcome','SERVICE_TAX_MAPPING_PROPOSED','proposal_id',proposal,'content_hash',h);
end$$;
create function public.decide_service_tax_category_mapping_v1(p_proposal_id uuid,p_expected_content_hash text,p_approve boolean,p_approval_reference text,p_reason text)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$
declare tax_rule jsonb;p public.service_tax_mapping_proposals%rowtype;d public.service_tax_mapping_decisions%rowtype;source jsonb;env text;v_overlaps uuid[];response jsonb;h text;decision text:=case when p_approve then'APPROVED'else'REJECTED'end;approved timestamptz:=clock_timestamp();begin
 if not coalesce(private.service_tax_mapping_reviewer_v1(),false)then raise exception'SERVICE_TAX_FINANCE_AAL2_REQUIRED'using errcode='42501';end if;
 if p_approve is null or p_expected_content_hash is null or coalesce(p_approval_reference,'')!~'^[A-Za-z0-9][A-Za-z0-9._:/-]{2,199}$'or length(btrim(coalesce(p_reason,'')))not between 10 and 1000 then raise exception'INVALID_SERVICE_TAX_DECISION'using errcode='22023';end if;
 select*into p from public.service_tax_mapping_proposals where id=p_proposal_id for update;
 if p.id is null or p.created_by=auth.uid()then raise exception'FOUR_EYES_REQUIRED'using errcode='42501';end if;
 if p.content_hash is distinct from p_expected_content_hash then raise exception'SERVICE_TAX_PROPOSAL_CHANGED'using errcode='40001';end if;
 select*into d from public.service_tax_mapping_decisions where proposal_id=p.id;
 if found then if d.decision is distinct from decision or d.decided_by is distinct from auth.uid()or d.approval_reference is distinct from p_approval_reference or d.reason is distinct from btrim(p_reason)then raise exception'SERVICE_TAX_PROPOSAL_ALREADY_DECIDED'using errcode='55000';end if;return d.response_body;end if;
 env:=private.service_tax_mapping_environment_v1();if env is distinct from p.environment then raise exception'SERVICE_TAX_DEPLOYMENT_CHANGED'using errcode='40001';end if;
 if(p.development_only or p_approval_reference~*'(^|[_:/-])(TEST|DEMO|FIXTURE|SANDBOX|MOCK)($|[_:/-])')and env not in('DEVELOPMENT','STAGING')then raise exception'SERVICE_TAX_DEMONSTRATION_FORBIDDEN'using errcode='42501';end if;
 if p_approval_reference~*'(^|[_:/-])(TEST|DEMO|FIXTURE|SANDBOX|MOCK)($|[_:/-])'and not p.development_only then raise exception'SERVICE_TAX_DEVELOPMENT_MARK_REQUIRED'using errcode='22023';end if;
 if p_approve then
  perform pg_advisory_xact_lock(hashtextextended('service-tax-scope:'||env||':'||p.service_version_id::text||':'||p.country_code||':'||p.currency::text,0));
  source:=private.service_tax_mapping_source_v1(p.service_version_id);
  if source->>'content_hash'is distinct from p.service_content_hash or private.service_tax_mapping_scope_hash_v1(env,p.service_version_id,p.country_code,p.currency)is distinct from p.expected_scope_hash then raise exception'SERVICE_TAX_SCOPE_CHANGED'using errcode='40001';end if;
  if not exists(select 1 from public.tax_categories where code=p.category_code and category_kind='SERVICE'and status='ACTIVE')then raise exception'SERVICE_TAX_CATEGORY_NOT_ACTIVE'using errcode='55000';end if;
  select coalesce(array_agg(m.id order by m.id),'{}')into v_overlaps from public.service_tax_category_mappings m where m.environment=env and m.service_version_id=p.service_version_id and m.country_code=p.country_code and m.currency=p.currency and private.service_tax_mapping_period_v1(m.id)&&daterange(p.valid_from,p.valid_until,'[]');
  if v_overlaps is distinct from p.supersedes_mapping_ids then raise exception'SERVICE_TAX_SUPERSESSION_REVIEW_REQUIRED'using errcode='55000';end if;
  if p.valid_from<((source->>'published_at')::timestamptz at time zone'Africa/Casablanca')::date or(source->>'retired_at'is not null and p.valid_from>((source->>'retired_at')::timestamptz at time zone'Africa/Casablanca')::date)then raise exception'SERVICE_TAX_SOURCE_DATE_MISMATCH'using errcode='55000';end if;
  begin tax_rule:=private.resolve_morocco_tax(p.category_code,p.valid_from,1);exception when sqlstate'P0002'then raise exception'SERVICE_TAX_RULE_REQUIRED'using errcode='55000';end;
  if tax_rule->>'professional_validation_status'is distinct from'VALIDATED'then raise exception'SERVICE_TAX_RULE_VALIDATION_REQUIRED'using errcode='55000';end if;
 end if;
 h:=private.canonical_request_hash(jsonb_build_object('proposal_hash',p.content_hash,'approval_reference',p_approval_reference,'reviewer',auth.uid(),'approved_at',approved));
 response:=jsonb_build_object('outcome',case when p_approve then'SERVICE_TAX_MAPPING_PUBLISHED'else'SERVICE_TAX_MAPPING_REJECTED'end,'proposal_id',p.id,'mapping_id',case when p_approve then p.id else null end,'content_hash',case when p_approve then h else p.content_hash end,'version',p.version,'environment',env,'development_only',p.development_only);
 insert into public.service_tax_mapping_decisions(proposal_id,decision,approval_reference,reason,decided_by,decided_at,response_body)values(p.id,decision,p_approval_reference,btrim(p_reason),auth.uid(),approved,response);
 if p_approve then
  insert into public.service_tax_category_mappings(id,environment,service_version_id,service_id,service_content_hash,service_snapshot,version,country_code,currency,category_code,valid_from,valid_until,development_only,approval_reference,approved_by,approved_at,content_hash)values(p.id,env,p.service_version_id,p.service_id,p.service_content_hash,p.service_snapshot,p.version,p.country_code,p.currency,p.category_code,p.valid_from,p.valid_until,p.development_only,p_approval_reference,auth.uid(),approved,h);
  insert into public.service_tax_mapping_supersessions(mapping_id,by_mapping_id,effective_from)select old.id,p.id,greatest(p.valid_from,old.valid_from)from public.service_tax_category_mappings old where old.id=any(p.supersedes_mapping_ids);

 end if;
 insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)select library.steward_organization_id,auth.uid(),'USER','tax.service_mapping.'||lower(decision),'service_tax_mapping',p.id::text,p.id,jsonb_build_object('service_version_id',p.service_version_id,'proposal_hash',p.content_hash,'content_hash',h,'approval_reference',p_approval_reference,'development_only',p.development_only),repeat('0',64)from public.catalog_libraries library where id=p.library_id;
 return response;
end$$;

-- Restricted operator views never expose unreviewed caller classification as an effective policy.
create function public.list_service_tax_category_sources_v1(p_search text default '',p_page integer default 1)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private as $$
declare result jsonb;total bigint;begin
 if not coalesce(private.service_tax_mapping_reviewer_v1(),false)then raise exception'SERVICE_TAX_FINANCE_AAL2_REQUIRED'using errcode='42501';end if;
 if p_page is null or p_page not between 1 and 100000 or p_search is null or length(p_search)>200 then raise exception'INVALID_SERVICE_TAX_PAGE'using errcode='22023';end if;
 select count(*)into total from public.catalog_service_versions v join public.catalog_services s on s.id=v.service_id where v.status in('PUBLISHED','RETIRED')and v.published_at is not null and s.status<>'ARCHIVED'and(position(lower(p_search)in lower(v.name_fr||' '||v.name_ar||' '||s.code))>0);
 select coalesce(jsonb_agg(row order by row->>'code',row->>'id'),'[]')into result from(select jsonb_build_object('id',v.id,'code',s.code,'name_fr',v.name_fr,'name_ar',v.name_ar,'version',v.version,'content_hash',v.content_hash,'status',v.status,'published_at',v.published_at)row from public.catalog_service_versions v join public.catalog_services s on s.id=v.service_id where v.status in('PUBLISHED','RETIRED')and v.published_at is not null and s.status<>'ARCHIVED'and(position(lower(p_search)in lower(v.name_fr||' '||v.name_ar||' '||s.code))>0)order by s.code,v.id limit 25 offset(p_page-1)*25)items;
 return jsonb_build_object('items',result,'page',p_page,'page_size',25,'total',total,'has_next',p_page::bigint*25<total);
end$$;
create function public.get_service_tax_category_mapping_context_v1(p_service_version_id uuid,p_country_code text,p_currency char(3),p_page integer default 1)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private as $$
declare source jsonb;env text;items jsonb;categories jsonb;total bigint;begin
 if not coalesce(private.service_tax_mapping_reviewer_v1(),false)then raise exception'SERVICE_TAX_FINANCE_AAL2_REQUIRED'using errcode='42501';end if;
 if p_page is null or p_page not between 1 and 100000 or p_country_code is null or p_country_code!~'^[A-Z]{2}$'or p_currency is null or p_currency!~'^[A-Z]{3}$'then raise exception'INVALID_SERVICE_TAX_SCOPE'using errcode='22023';end if;
 env:=private.service_tax_mapping_environment_v1();source:=private.service_tax_mapping_source_v1(p_service_version_id);
 select count(*)into total from public.service_tax_mapping_proposals p where p.environment=env and p.service_version_id=p_service_version_id and p.country_code=p_country_code and p.currency=p_currency;
 select coalesce(jsonb_agg(item order by(item->>'version')::integer desc),'[]')into items from(select jsonb_build_object('id',p.id,'version',p.version,'category_code',p.category_code,'valid_from',p.valid_from,'valid_until',p.valid_until,'development_only',p.development_only,'reason',p.reason,'content_hash',p.content_hash,'supersedes_mapping_ids',p.supersedes_mapping_ids,'created_at',p.created_at,'decision',d.decision,'approval_reference',d.approval_reference,'mapping_content_hash',m.content_hash,'effective_period',case when m.id is not null then private.service_tax_mapping_period_v1(m.id)::text end,'can_decide',d.proposal_id is null and p.created_by<>auth.uid())item from public.service_tax_mapping_proposals p left join public.service_tax_mapping_decisions d on d.proposal_id=p.id left join public.service_tax_category_mappings m on m.id=p.id where p.environment=env and p.service_version_id=p_service_version_id and p.country_code=p_country_code and p.currency=p_currency order by p.version desc limit 25 offset(p_page-1)*25)rows;
 select coalesce(jsonb_agg(jsonb_build_object('code',code,'name_fr',name_fr,'name_ar',name_ar)order by code),'[]')into categories from public.tax_categories where status='ACTIVE'and category_kind='SERVICE';
 return jsonb_build_object('source',source,'environment',env,'country_code',p_country_code,'currency',p_currency,'scope_hash',private.service_tax_mapping_scope_hash_v1(env,p_service_version_id,p_country_code,p_currency),'categories',categories,'proposals',items,'page',p_page,'page_size',25,'total',total,'has_next',p_page::bigint*25<total);
end$$;
create function public.get_service_tax_category_policy_v1(p_service_version_id uuid,p_country_code text,p_currency char(3),p_effective_on date)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private as $$begin
 if auth.role()is distinct from'service_role'and not coalesce(private.service_tax_mapping_reviewer_v1(),false)then raise exception'SERVICE_TAX_FINANCE_AAL2_REQUIRED'using errcode='42501';end if;
 return private.resolve_service_tax_category_v1(p_service_version_id,p_country_code,p_currency,p_effective_on);
end$$;
revoke all on function private.service_tax_mapping_environment_v1(),private.service_tax_mapping_source_v1(uuid),private.service_tax_mapping_scope_hash_v1(text,uuid,text,char(3)),private.service_tax_mapping_period_v1(uuid),private.resolve_service_tax_category_v1(uuid,text,char(3),date)from public,anon,authenticated,service_role;
revoke all on function public.propose_service_tax_category_mapping_v1(uuid,text,text,text,char(3),text,date,date,boolean,uuid[],text,uuid),public.decide_service_tax_category_mapping_v1(uuid,text,boolean,text,text),public.list_service_tax_category_sources_v1(text,integer),public.get_service_tax_category_mapping_context_v1(uuid,text,char(3),integer),public.get_service_tax_category_policy_v1(uuid,text,char(3),date)from public,anon,authenticated,service_role;
grant execute on function public.propose_service_tax_category_mapping_v1(uuid,text,text,text,char(3),text,date,date,boolean,uuid[],text,uuid),public.decide_service_tax_category_mapping_v1(uuid,text,boolean,text,text),public.list_service_tax_category_sources_v1(text,integer),public.get_service_tax_category_mapping_context_v1(uuid,text,char(3),integer),public.get_service_tax_category_policy_v1(uuid,text,char(3),date)to authenticated;
grant execute on function public.get_service_tax_category_policy_v1(uuid,text,char(3),date)to service_role;
-- Existing category codes are uppercase; command-scope identifiers must remain lowercase.
-- Keep the fiscal category unchanged and preserve the mature engine's OID and all guards.
do $$declare definition text;begin
 definition:=pg_get_functiondef('public.propose_morocco_tax_rule(uuid,text,text,integer,integer,jsonb,text,date,date,text,text,uuid)'::regprocedure);
 if position('''morocco.tax.rule.propose.''||p_category_code' in definition)=0 then raise exception'TAX_PROPOSAL_SCOPE_PATCH_SOURCE_MISMATCH';end if;
 execute replace(definition,'''morocco.tax.rule.propose.''||p_category_code','''morocco.tax.rule.propose.''||lower(p_category_code)');
end$$;
